function Pill({children,color='mint',icon}){return <span className={'pill '+color}>{icon&&<Icon name={icon} size={13}/>} {children}</span>}
function SectionTitle({eyebrow,title,desc,action}){return <div className="section-title"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>{action}</div>}
