function Coach({p,enabled,award,go}){const[messages,setMessages]=useState([{role:'assistant',content:'Hi! Tell me what you’d like to practise today. We can talk about travel, work, daily life, or anything on your mind.'}]),[input,setInput]=useState(''),[busy,setBusy]=useState(false),[mode,setMode]=useState('Conversation partner'),[error,setError]=useState('');const send=async(e)=>{e.preventDefault();if(!input.trim()||!enabled)return;const next=[...messages,{role:'user',content:input.trim()}];setMessages(next);setInput('');setBusy(true);setError('');try{const d=await api('coach',{messages:next.filter(m=>m.role==='user'||m.role==='assistant').slice(1),level:p.level,goal:p.goal,mode});setMessages([...next,{role:'assistant',content:d.reply}])}catch(e){setError(e.message)}setBusy(false)};const finish=()=>{award({id:'coach',title:'AI conversation',date:new Date().toISOString(),words:[],summary:'Completed a free conversation practice.'});go('progress')};return <div className="page"><SectionTitle eyebrow="YOUR AI TEACHER" title="A coach for every kind of practice" desc="Talk naturally, ask questions, or work through something you find difficult."/><div className="coach-layout"><div className="coach-main"><div className="coach-heading"><div className="coach-identity"><div className="coach-avatar">✦</div><div><b>USAM Coach</b><small><span className={enabled?'status-dot':'status-dot off'}/>{enabled?'Ready to practise':'Live AI connection required'}</small></div></div><select aria-label="Coach role" value={mode} onChange={e=>setMode(e.target.value)}>{['Conversation partner','Speaking coach','Grammar tutor','Writing coach','Interview coach','Study planner'].map(x=><option key={x}>{x}</option>)}</select></div><div className="coach-messages">{messages.map((m,i)=><div className={'bubble-row '+(m.role==='user'?'mine':'')} key={i}><span className="bubble-avatar">{m.role==='user'?(p.name?.[0]||'Y').toUpperCase():'✦'}</span><div className="bubble"><small>{m.role==='user'?'YOU':'USAM COACH'}</small><p>{m.content}</p>{m.role==='assistant'&&<button className="speak-inline" onClick={()=>say(m.content)} aria-label="Read aloud"><Icon name="Volume2" size={15}/></button>}</div></div>)}{busy&&<div className="typing">Thinking about your answer •••</div>}</div>{!enabled&&<div className="coach-offline"><Icon name="PlugZap" size={18}/><div><b>Live AI is not connected on this deployment.</b><p>Add the server-side API key to unlock free conversation. You can use all guided practice scenes now.</p></div><button onClick={()=>go('world')}>Open a scene <Icon name="ArrowRight" size={15}/></button></div>}{error&&<div className="inline-error" role="alert">{error}</div>}<form className="chat-composer" onSubmit={send}><button type="button" className="composer-mic" onClick={()=>listen(t=>setInput(t))} title="Dictate"><Icon name="Mic" size={19}/></button><input value={input} onChange={e=>setInput(e.target.value)} placeholder="Ask or say anything in English…" disabled={!enabled} aria-label="Your message"/><button className="send-button" type="submit" disabled={!input.trim()||busy||!enabled}><Icon name="ArrowUp"/></button></form></div><aside className="coach-side"><div className="panel"><span className="eyebrow">HOW I CAN HELP</span><div className="coach-prompts">{['Let’s practise for a job interview.','Help me tell a story in past tense.','Correct one important mistake at a time.','I have 10 minutes. What should I practise?'].map(x=><button key={x} onClick={()=>setInput(x)} disabled={!enabled}>{x}<Icon name="ArrowUpRight" size={15}/></button>)}</div></div><div className="panel"><span className="eyebrow">TEACHING APPROACH</span><p>I’ll keep the conversation moving, give hints when useful, and let you try again. A live AI response may be imperfect.</p></div>{messages.length>2&&<Button variant="secondary" onClick={finish}>End conversation</Button>}</aside></div></div>}
function Pronunciation({award}){const[phrase,setPhrase]=useState('Could you tell me where the gate is?'),[heard,setHeard]=useState(''),[recording,setRecording]=useState(false),[attempts,setAttempts]=useState(0),[rate,setRate]=useState(.9);const choices=['Could you tell me where the gate is?','I would like to book a room, please.','I have been working on this project.','What time does the meeting start?'];const clean=x=>x.toLowerCase().replace(/[^a-z\s]/g,'').trim().split(/\s+/);const a=clean(phrase),b=clean(heard),matches=a.filter((w,i)=>b[i]===w).length;const result=heard?Math.round(matches/a.length*100):null;const practice=()=>{setRecording(true);const ok=listen(t=>{setHeard(t);setAttempts(v=>v+1);award({id:'pronunciation',title:'Speaking attempt',date:new Date().toISOString(),words:[],summary:'Practised a sentence by speaking it aloud.'})},()=>setRecording(false));if(!ok){setRecording(false);alert('Speech recognition is unavailable in this browser. Try Chrome with microphone permission on HTTPS.')}};return <div className="page"><SectionTitle eyebrow="PRONUNCIATION LAB" title="Hear it. Say it. Try again." desc="Practise a useful sentence and compare the words your browser understood."/><div className="lab-layout"><div className="panel lab-main"><div className="lab-top"><Pill color="blue" icon="AudioLines">SPEAKING PRACTICE</Pill><span>ATTEMPT {attempts+1}</span></div><div className="lab-sound"><div className="lab-orb"><Icon name="AudioLines" size={41}/></div><div className="sound-bars">{Array.from({length:17},(_,i)=><i key={i} style={{height:(12+(i*17)%42)+'px'}}/>)}</div></div><span className="eyebrow">SAY THIS SENTENCE</span><h2>“{phrase}”</h2><div className="lab-actions"><Button onClick={()=>say(phrase,rate)} variant="secondary" icon="Volume2">Listen</Button><Button onClick={practice} icon="Mic" disabled={recording}>{recording?'Listening…':'Start speaking'}</Button></div><div className="speed-control"><span>Playback speed</span><button className={rate===.7?'selected':''} onClick={()=>setRate(.7)}>Slow</button><button className={rate===.9?'selected':''} onClick={()=>setRate(.9)}>Normal</button><button className={rate===1.1?'selected':''} onClick={()=>setRate(1.1)}>Faster</button></div>{heard&&<div className="transcript-result"><small>YOUR TRANSCRIPT</small><p>“{heard}”</p><div className="transcript-track"><span style={{width:result+'%'}}/></div><b>{result}% word-position match</b><p className="note">This compares recognised words. It cannot assess phonemes, accent, or pronunciation accuracy. Try again if the browser misheard you.</p></div>}</div><aside className="panel lab-side"><span className="eyebrow">CHOOSE A PHRASE</span>{choices.map((x,i)=><button className={phrase===x?'active':''} key={i} onClick={()=>{setPhrase(x);setHeard('')}}><span>0{i+1}</span>{x}<Icon name="ArrowRight" size={16}/></button>)}<div className="lab-tip"><Icon name="Lightbulb" size={17}/><span>Listen once, speak naturally, then repeat more clearly if needed.</span></div></aside></div></div>}
function Writing({award}){const[prompt,setPrompt]=useState('Write three sentences about a trip you would like to take.'),[text,setText]=useState(''),[feedback,setFeedback]=useState(null),[busy,setBusy]=useState(false);const prompts=['Write three sentences about a trip you would like to take.','Describe a project you are proud of and your role in it.','Write a polite message asking a client for more details.'];const check=async()=>{setBusy(true);try{const d=await api('feedback',{text});setFeedback(d);award({id:'writing',title:'Writing practice',date:new Date().toISOString(),words:[],summary:'Wrote and reviewed a response.'})}catch{}setBusy(false)};return <div className="page"><SectionTitle eyebrow="WRITING STUDIO" title="Put your ideas into words" desc="Write a response, get a few useful checks, and make your next draft clearer."/><div className="writing-layout"><div className="panel writing-main"><Pill color="coral" icon="PenLine">GUIDED WRITING</Pill><h2>{prompt}</h2><textarea value={text} onChange={e=>{setText(e.target.value);setFeedback(null)}} placeholder="Start writing here…" aria-label="Your writing"/><div className="writing-footer"><span>{text.trim()?text.trim().split(/\s+/).length:0} words</span><Button onClick={check} disabled={!text.trim()||busy} icon="ArrowRight">Review my writing</Button></div>{feedback&&<div className="writing-feedback"><span className="eyebrow">WRITING CHECK</span><h3>{feedback.wordCount<12?'Try expanding your idea.':'A good start. Keep refining.'}</h3><p>You used {feedback.uniqueWords} distinct words in {feedback.wordCount} words.</p>{feedback.signals.length?<ul>{feedback.signals.map((x,i)=><li key={i}><Icon name="Lightbulb" size={16}/>{x}</li>)}</ul>:<p>No simple rule flagged an issue. Read it aloud and check whether your main point is clear.</p>}<small>Automated surface checks, not a full grammar or CEFR evaluation.</small></div>}</div><aside className="panel writing-side"><span className="eyebrow">CHOOSE A PROMPT</span>{prompts.map((x,i)=><button className={prompt===x?'active':''} key={i} onClick={()=>{setPrompt(x);setFeedback(null);setText('')}}><span>0{i+1}</span>{x}<Icon name="ArrowRight" size={16}/></button>)}</aside></div></div>}
const storySteps=[{scene:'The last train',text:'You arrive at a small station just as the final train is about to leave. A visitor asks, “Is this the train to the city centre?”',choices:[['Yes, this is the right train.','help'],['I’m not sure. Let’s ask the conductor.','ask']]},{scene:'A new clue',text:'The conductor smiles and points to the timetable. “This train goes to the old town. The city-centre train leaves from platform four.”',choices:[['Thank you. Where is platform four?','ask'],['We should hurry to platform four!','help']]},{scene:'You made it',text:'You and the visitor reach platform four in time. “Thanks for helping me,” they say. You used English to solve a real problem.',choices:[]}];
function Story({award}){const[step,setStep]=useState(0),[choices,setChoices]=useState([]);const sceneText=step===1?(choices[0]?.startsWith('Yes')?'You guide the visitor onto the train. The conductor checks your tickets and says, “This one goes to the old town. For the city centre, use platform four.”':'You ask the conductor before boarding. “Good question,” they say. “This train goes to the old town. The city-centre train leaves from platform four.”'):step===2?(choices[1]?.startsWith('Thank')?'The conductor points you toward platform four. You and the visitor reach it in time. “Thanks for helping me,” they say.':'You follow the signs and hurry to platform four. You and the visitor make it just in time. “Thanks for helping me,” they say.'):storySteps[step].text;const choose=(text)=>{setChoices([...choices,text]);setStep(step+1);if(step===1)award({id:'story',title:'The last train',date:new Date().toISOString(),words:['platform','timetable'],summary:'Completed an interactive story.'})};return <div className="page"><SectionTitle eyebrow="INTERACTIVE STORIES" title="A story you help unfold" desc="Read, listen, choose, and see what your words make possible."/><div className="story-layout"><div className="story-visual"><div className="story-sky"><span>✦</span><span>✦</span><span>✧</span></div><div className="story-moon"/><div className="story-mountain m1"/><div className="story-mountain m2"/><div className="story-platform"/><div className="story-train"><span/><span/><span/></div><div className="story-caption">USAM STORIES · CHAPTER 01</div></div><div className="panel story-copy"><Pill color="lilac">SCENE {Math.min(step+1,3)} OF 3</Pill><h2>{storySteps[step].scene}</h2><p>{sceneText}</p><button className="listen-story" onClick={()=>say(sceneText,.85)}><Icon name="Volume2" size={18}/> Listen to the scene</button>{step<2?<><span className="eyebrow">WHAT DO YOU SAY?</span><div className="story-choices">{storySteps[step].choices.map(([text],i)=><button key={i} onClick={()=>choose(text)}>{text}<Icon name="ArrowRight" size={17}/></button>)}</div></>:<div className="story-end"><Icon name="CheckCircle2"/><b>Story complete</b><p>Words to remember: platform · timetable</p><Button variant="secondary" onClick={()=>{setStep(0);setChoices([])}}>Read again</Button></div>}</div></div></div>}
function Group({p}){const[code,setCode]=useState(''),[joined,setJoined]=useState(false),[name,setName]=useState(p.name||''),[text,setText]=useState(''),[messages,setMessages]=useState([]),[members,setMembers]=useState([]),[error,setError]=useState('');const ws=useRef(null);useEffect(()=>()=>ws.current?.close(),[]);const connect=()=>{const c=code.trim().toUpperCase().replace(/[^A-Z0-9]/g,'');if(c.length<4||!name.trim()){setError('Enter your name and a room code of at least four characters.');return}const protocol=location.protocol==='https:'?'wss':'ws';const socket=new WebSocket(`${protocol}://${location.host}/api/rooms?code=${encodeURIComponent(c)}&name=${encodeURIComponent(name)}`);ws.current=socket;socket.onopen=()=>{setJoined(true);setError('')};socket.onmessage=e=>{const d=JSON.parse(e.data);if(d.type==='members')setMembers(d.members);else setMessages(v=>[...v,d])};socket.onerror=()=>setError('Could not join this room. Check your connection.');socket.onclose=e=>{setJoined(false);if(e.code===1008)setError('This room is invalid or full.')}};const leave=()=>{ws.current?.close();setJoined(false)};const send=e=>{e.preventDefault();if(text.trim()&&ws.current?.readyState===1){ws.current.send(JSON.stringify({type:'message',text:text.trim()}));setText('')}};return <div className="page"><SectionTitle eyebrow="PRACTISE TOGETHER" title="A room to find your voice" desc="Invite up to three other learners. The coach can offer a simple prompt when asked."/><div className="group-layout">{!joined?<div className="panel group-start"><div className="group-illustration"><Icon name="UsersRound" size={48}/><span>✦</span></div><h2>Better together.</h2><p>Create a room code and share it with people you know, or enter a code you received.</p><label>Your name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Your first name" maxLength={24}/></label><label>Room code<input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="For example, TALK24" maxLength={8}/></label><Button onClick={connect} icon="ArrowRight">Join room</Button>{error&&<p className="inline-error">{error}</p>}<small>Room messages live in server memory while participants are connected. This starter room does not analyse group speech.</small></div>:<div className="group-chat panel"><div className="group-head"><div><span className="eyebrow">LIVE ROOM</span><h2>{code.toUpperCase()}</h2></div><button className="text-link" onClick={leave}>Leave room <Icon name="LogOut" size={17}/></button></div><div className="group-members">{members.map((n,i)=><Pill key={i} color="mint" icon="CircleUserRound">{n}</Pill>)}</div><div className="group-messages">{messages.length===0&&<div className="empty-state"><Icon name="MessagesSquare" size={32}/><b>Start the conversation</b><p>Try introducing yourself or asking where someone would like to travel.</p></div>}{messages.map((m,i)=><div key={i} className={'group-message '+(m.type==='coach'?'from-coach':'')}><b>{m.type==='coach'?'Coach hint':m.name}</b><p>{m.text}</p></div>)}</div><form onSubmit={send} className="chat-composer"><input value={text} onChange={e=>setText(e.target.value)} placeholder="Say something to the room…" maxLength={600}/><button className="send-button" disabled={!text.trim()}><Icon name="ArrowUp"/></button></form></div>}<aside className="group-info"><div className="panel"><span className="eyebrow">ROOM GUIDE</span><h3>How to practise together</h3><ol><li>Choose a place or topic.</li><li>Give each person a turn.</li><li>Ask follow-up questions.</li><li>Type “hint” if the conversation stalls.</li></ol></div><div className="panel"><Icon name="ShieldCheck"/><p>Use a code shared privately with your group. Rooms hold up to four people; there is no account or moderation in this starter.</p></div></aside></div></div>}
function Review({p,update}){const[index,setIndex]=useState(0),[flipped,setFlipped]=useState(false),[filter,setFilter]=useState('due');const cards=filter==='due'?p.reviews.filter(r=>!r.due||r.due<=Date.now()):p.reviews;const card=cards[index]||cards[0];const grade=(good)=>{if(!card)return;const reviews=p.reviews.map(r=>r.word===card.word?{...r,interval:good?Math.max(1,Math.round((r.interval||1)*(r.ease||2.5))):1,ease:Math.max(1.3,(r.ease||2.5)+(good?.1:-.2)),due:Date.now()+(good?Math.max(1,(r.interval||1))*86400000:600000)}:r);update({reviews});setIndex(0);setFlipped(false)};return <div className="page"><SectionTitle eyebrow="MEMORY & REVIEW" title="Make new words stick" desc="Bring words back at the right moment, then use them in a new context." action={<div className="segmented"><button className={filter==='due'?'active':''} onClick={()=>{setFilter('due');setIndex(0)}}>Due now</button><button className={filter==='all'?'active':''} onClick={()=>{setFilter('all');setIndex(0)}}>All words</button></div>}/>{card?<div className="review-layout"><div className="review-card" onClick={()=>setFlipped(!flipped)} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')setFlipped(!flipped)}}><span className="eyebrow">WORD {Math.min(index+1,cards.length)} / {cards.length}</span><div className="review-center"><Icon name={flipped?'MessageCircle':'BookOpen'} size={30}/><h2>{flipped?`Try using “${card.word}” in a sentence.`:card.word}</h2><p>{flipped?'Say your sentence aloud, then mark whether you remembered it.':'Say what this means or use it in a sentence.'}</p></div><span className="review-flip">{flipped?'Tap to see the word':'Tap to reveal a prompt'} <Icon name="RotateCcw" size={16}/></span></div><div className="review-buttons"><Button variant="secondary" onClick={()=>grade(false)}>Again</Button><Button onClick={()=>grade(true)}>I remembered</Button></div><p className="review-footnote">Review timing is an initial local scheduler; it will be replaced by a calibrated FSRS integration.</p></div>:<div className="empty-panel"><div className="empty-icon"><Icon name="Layers3" size={34}/></div><h2>{p.reviews.length?'All caught up!':'Your word collection starts with a conversation.'}</h2><p>{p.reviews.length?'Come back later for your next review.':'Use target words in a guided scene and they’ll appear here for review.'}</p><a className="btn primary" href="#world">Explore a scene <Icon name="ArrowRight" size={17}/></a></div>}</div>}
function Progress({p}){const skills=Object.entries(p.skills||{}),recent=p.sessions.slice(0,5);return <div className="page"><SectionTitle eyebrow="YOUR LEARNING EVIDENCE" title="See how far you’ve come" desc="A view of your practice, skill estimates, and what to work on next."/><div className="progress-overview"><div className="progress-level"><span className="eyebrow">CURRENT STARTING ESTIMATE</span><div>{p.level}<span>✦</span></div><p>Different skills move at different speeds. This is a working estimate, not an official certificate.</p></div><Metric icon="MessageSquare" label="SESSIONS" value={p.sessions.length} detail="Completed activities" color="mint"/><Metric icon="Zap" label="PRACTICE XP" value={p.xp} detail="Meaningful participation" color="gold"/><Metric icon="Flame" label="STREAK" value={p.streak} detail="Days of practice" color="coral"/></div><div className="progress-grid"><div className="panel"><SectionTitle eyebrow="SKILL MAP" title="Your skills, one by one"/><div className="skills-list full">{skills.map(([name,v])=><div className="skill-row" key={name}><span>{name}</span><div className="skill-track"><i style={{width:v+'%'}}/></div><b>{v}</b></div>)}</div><p className="note">Initial values reflect a short placement exercise. Other skills stay provisional until supported assessments are available.</p></div><div className="panel"><SectionTitle eyebrow="SESSION HISTORY" title="The work you’ve done"/>{recent.length?<div className="session-list">{recent.map((s,i)=><div key={i}><span className="session-icon"><Icon name={s.id==='story'?'BookOpen':s.id==='writing'?'PenLine':'MessageCircle'} size={19}/></span><div><b>{s.title}</b><small>{new Date(s.date).toLocaleDateString()} · {s.summary}</small></div><Icon name="Check" size={16}/></div>)}</div>:<div className="empty-small"><Icon name="Sprout" size={27}/><p>Your first session will appear here.</p></div>}</div></div></div>}
function Settings({p,update,theme,setTheme,setNotice}){const exportData=()=>{const b=new Blob([JSON.stringify(p,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='usam-language-progress.json';a.click();URL.revokeObjectURL(a.href)};return <div className="page"><SectionTitle eyebrow="MAKE IT YOURS" title="Your learning settings" desc="Set a goal, make practice fit your day, and control your local learning record."/><div className="settings-grid"><div className="panel settings-panel"><h3>My learning profile</h3><label>Name<input value={p.name} onChange={e=>update({name:e.target.value})}/></label><label>Why are you learning?<select value={p.goal} onChange={e=>update({goal:e.target.value})}>{['Travel & everyday life','Career & interviews','Study & university','Freelancing & clients','Entrepreneurship & business','Personal growth'].map(x=><option key={x}>{x}</option>)}</select></label><label>Minutes per day<select value={p.minutes} onChange={e=>update({minutes:Number(e.target.value)})}>{[5,10,20,30,45,60].map(x=><option key={x} value={x}>{x} minutes</option>)}</select></label><label>Appearance<select value={theme} onChange={e=>setTheme(e.target.value)}><option value="dark">Dark · USAM</option><option value="light">Light</option></select></label></div><div className="panel settings-panel"><h3>Language packs</h3><p>The learning engine uses language-specific content and speech adapters. English is the current active pack.</p><div className="pack-list">{languagePacks.map(l=><div key={l.code}><span>{l.native}<small>{l.name}</small></span><Pill color={l.state==='active'?'mint':'neutral'}>{l.state==='active'?'Active':'Planned'}</Pill></div>)}</div></div><div className="panel settings-panel"><h3>Your data</h3><p>This starter stores your profile in this browser. Export a copy or clear the local record.</p><div className="settings-actions"><Button variant="secondary" icon="Download" onClick={exportData}>Export JSON</Button><Button variant="danger" icon="Trash2" onClick={()=>{if(confirm('Remove the local learning record from this browser?')){localStorage.removeItem('usam.language.profile');location.reload()}}}>Clear local progress</Button></div><small>Room messages are temporary and do not appear in your export. The live coach, when configured, sends text to its provider.</small></div></div></div>}
function Engines(){const totals=Object.values(engineGroups).flat().length;return <div className="page"><SectionTitle eyebrow="BEHIND THE LEARNING EXPERIENCE" title="One connected learning system" desc="The product plan brings the learner, language knowledge, coaching, and immersive experiences together."/><div className="engine-hero"><div><Pill color="gold">THE PRODUCT ARCHITECTURE</Pill><h2>{totals} capabilities.<br/><em>One learning journey.</em></h2><p>Each language pack supplies its own knowledge and speech resources; core learning logic can be reused. Capabilities below are a roadmap, not a claim that every service is live here.</p></div><div className="engine-graphic"><span>Learner model</span><span>Learning engines</span><span>Language pack</span><span>Real-world practice</span></div></div><div className="engine-grid">{Object.entries(engineGroups).map(([name,items],i)=><div className="panel engine-group" key={name}><span className="engine-index">0{i+1}</span><h3>{name}</h3><div className="engine-chips">{items.map(x=><span key={x}>{x}</span>)}</div></div>)}</div><div className="architecture-note"><Icon name="ShieldCheck"/><div><b>Quality before release</b><p>New sources and generated lessons need rights checks, review, evaluation, and a human approval gate before publication.</p></div></div></div>}
function Onboarding({update}){const[step,setStep]=useState(0),[name,setName]=useState(''),[goal,setGoal]=useState('Travel & everyday life'),[minutes,setMinutes]=useState(20),[questions,setQuestions]=useState([]),[answers,setAnswers]=useState({}),[idx,setIdx]=useState(0),[result,setResult]=useState(null);useEffect(()=>{api('assessment').then(d=>setQuestions(d.questions)).catch(()=>{})},[]);const submit=async()=>{try{setResult(await api('assessment',{answers}));setStep(2)}catch{setStep(2);setResult({level:'A2',skills:initialProfile.skills,correct:0,total:6,confidence:'Provisional estimate'})}};const done=()=>update({name:name.trim()||'Learner',goal,minutes,assessmentDone:true,level:result?.level||'A2',skills:result?.skills||initialProfile.skills});const q=questions[idx];return <div className="onboarding" role="dialog" aria-modal="true" aria-label="Welcome to USAM Language"><div className="onboard-card"><div className="onboard-logo"><img src="/brand/usam-wordmark.png" alt="USAM"/><span>LANGUAGE</span></div><div className="onboard-progress"><span style={{width:(step===0?20:step===1?30+idx*10:100)+'%'}}/></div>{step===0?<div className="onboard-body"><span className="eyebrow">YOUR JOURNEY STARTS HERE</span><h1>English for where <em>you’re going.</em></h1><p>Tell us a little about you. We’ll shape a first learning path and make it more accurate as you practise.</p><label>What should we call you?<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="Your first name"/></label><label>What is your main goal?<select value={goal} onChange={e=>setGoal(e.target.value)}>{['Travel & everyday life','Career & interviews','Study & university','Freelancing & clients','Entrepreneurship & business','Personal growth'].map(x=><option key={x}>{x}</option>)}</select></label><label>Time you can practise each day<select value={minutes} onChange={e=>setMinutes(Number(e.target.value))}>{[5,10,20,30,45,60].map(x=><option key={x} value={x}>{x} minutes</option>)}</select></label><Button onClick={()=>setStep(1)} icon="ArrowRight">Find my starting point</Button><small>About 2 minutes · Your answers stay in this browser</small></div>:step===1?<div className="onboard-body"><span className="eyebrow">A QUICK STARTING CHECK · {idx+1} / {questions.length||6}</span><h2>{q?.question||'Loading your starting check…'}</h2>{q?.audio&&<button className="listen-question" onClick={()=>say(q.audio,.85)}><Icon name="Volume2"/> Listen to the sentence</button>}<div className="answer-options">{q?.options.map((x,i)=><button key={i} className={answers[q.id]===i?'chosen':''} onClick={()=>setAnswers({...answers,[q.id]:i})}><span>{String.fromCharCode(65+i)}</span>{x}</button>)}</div><div className="onboard-bottom"><button onClick={()=>setIdx(Math.max(0,idx-1))} disabled={idx===0}>Back</button><Button disabled={!q||answers[q.id]===undefined} onClick={()=>idx<questions.length-1?setIdx(idx+1):submit()} icon="ArrowRight">{idx<questions.length-1?'Next question':'See my path'}</Button></div><small>Short placement checks are provisional. Speaking and writing need later evidence.</small></div>:<div className="onboard-body result-body"><div className="result-icon"><Icon name="Sparkles" size={30}/></div><span className="eyebrow">YOUR STARTING POINT</span><h1>Welcome to your <em>{result?.level} journey.</em></h1><p>You answered {result?.correct} of {result?.total} starting questions correctly. This is a first estimate that will change as you learn.</p><div className="result-summary"><span><Icon name="Target"/> Goal <b>{goal}</b></span><span><Icon name="Clock3"/> Daily time <b>{minutes} minutes</b></span></div><Button onClick={done} icon="ArrowRight">Enter my learning space</Button></div>}</div><div className="onboard-aside"><span className="onboard-asterisk">✳</span><span>LEARN BY LIVING IT</span><div className="onboard-orb">✦</div><h2>Not just lessons.<br/>A world of <em>possibility.</em></h2><p>Speak, explore, make mistakes, and keep going. Your English grows with every real attempt.</p><div className="onboard-foot"><span>USAM</span><span>LEARN · GROW · EARN</span></div></div></div>}
if('serviceWorker'in navigator&&import.meta.env.PROD)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
createRoot(document.getElementById('root')).render(<App/>);
